INSERT INTO `services_i18n` (`id`, `service_id`, `locale`, `slug`, `name`, `summary`, `content`, `image_alt`, `meta_title`, `meta_description`, `meta_keywords`) VALUES
('10000001-0000-4000-8000-020000000001', '10000000-0000-4000-8000-020000000001', 'tr', 'osgb-isletme-yonetim-sistemi', 'OSGB işletme yönetim sistemi', 'OSGB''nizin firmalarını, İSG ziyaretlerini, uzman kapasitesini, aylık cirosunu ve tahsilatını tek panelden yönetin. İBYS Bakanlığa veri gönderir; işinizi yönetmez. Bu sistem tam olarak o boşluğu kapatır.', '{"source":"vertical_product","segment":"OSGB","packages":[{"title":"Operasyon Çekirdeği","price":60000,"currency":"TRY","duration_days":30,"revisions":2,"features":["Firma ve sözleşme yönetimi","İSG ziyaret takibi (12 aylık takvim, eksik ziyaret uyarısı)","Görev yönetimi","Arşiv ve evrak checklist''i","Sağlık raporu takibi","Rol ve yetki matrisi","İSG-KATİP / Excel veri aktarımı"]},{"title":"Ticari Yönetim","price":36000,"currency":"TRY","duration_days":30,"revisions":2,"features":["Kişi başı fiyattan otomatik aylık ciro hesabı","Teklif süreçleri","Cari ve tahsilat takibi","Uzman/hekim kapasite ve doluluk raporu"]},{"title":"İK ve Performans","price":24000,"currency":"TRY","duration_days":30,"revisions":2,"features":["Personel ve İK takibi","Aylık hedef ve performans","Yönetim panosu ve raporlar"]}],"html":"OSGB''ler yasal uyum için İBYS yazılımı kullanır; ancak İBYS Bakanlığa veri göndermek içindir, işletmeyi yönetmez. Hangi firmaya kim gitti, hangi ziyaret eksik kaldı, uzmanın kapasitesi doldu mu, bu ay ne kadar ciro edilecek, kim ödemedi — bunların hepsi genellikle Excel''de kalır.\\n\\nOSGB İşletme Yönetim Sistemi tam olarak bu katmanı kapatır:\\n\\n• Firma kartları — tehlike sınıfı, bölge, çalışan sayısı, kişi başı fiyat, sözleşme ve çıkış durumu\\n• İSG ziyaretleri — 12 aylık takvim, eksik ziyaret uyarısı, delil yükleme, ziyaret notunun firmaya iletilmesi\\n• Otomatik ciro — kişi başı fiyat ve çalışan sayısından aylık ciro hesabı; eksik faturalanan firma gözden kaçmaz\\n• Kapasite — atama süreleri ve periyotlardan uzman/hekim doluluk oranı\\n• Görev takibi, arşiv ve evrak checklist''i, tamamlanma yüzdesi\\n• Sağlık raporu ve tarama takibi, hekim ekranı\\n• Rol ve yetki yönetimi; mobil uyumlu arayüz\\n\\nMevcut Excel ve İSG-KATİP verileriniz sisteme aktarılır; sıfırdan veri girişi yapmazsınız. Veriler size aittir ve dilediğiniz zaman dışa aktarılabilir. Kullanıcı başına ücretlendirme yoktur; fiyat OSGB''nin ölçeğine göre belirlenir.","llms_summary":"GZL Teknoloji, OSGB''ler (Ortak Sağlık Güvenlik Birimi) için işletme yönetim sistemi geliştirir: firma ve sözleşme yönetimi, İSG ziyaret takibi, otomatik ciro hesabı, uzman/hekim kapasite takibi, sağlık raporu, arşiv ve tahsilat. İBYS uyum yazılımının yerine geçmez; onun kapsamadığı operasyon ve ticari yönetim katmanını kapatır.","tags":["OSGB","İSG","İş Sağlığı ve Güvenliği","Dikey Yazılım","İşletme Yönetimi"]}', 'OSGB işletme yönetim sistemi ekranı', 'OSGB İşletme Yönetim Sistemi | GZL Teknoloji', 'OSGB firmalarını, İSG ziyaretlerini, uzman kapasitesini, aylık ciroyu ve tahsilatı tek panelden yönetin. Excel''e son verin.', 'OSGB yazılımı, OSGB işletme yönetim sistemi, İSG ziyaret takibi, İSG-KATİP, iş sağlığı güvenliği yazılımı'),
('10000002-0000-4000-8000-020000000001', '10000000-0000-4000-8000-020000000001', 'en', 'ohs-provider-management-system', 'OHS provider management system', 'Manage your occupational health and safety company''s clients, site visits, expert capacity, monthly revenue and collections from a single panel. Compliance software reports to the ministry; it does not run your business.', '{"source":"vertical_product","segment":"OHS","packages":[{"title":"Operational Core","price":60000,"currency":"TRY","duration_days":30,"revisions":2,"features":["Client and contract management","Site visit tracking with missed-visit alerts","Task management","Archive and document checklist","Health report tracking","Roles and permissions","Data migration from Excel and registry"]},{"title":"Commercial Management","price":36000,"currency":"TRY","duration_days":30,"revisions":2,"features":["Automatic monthly revenue from per-capita pricing","Quotation workflow","Receivables and collection tracking","Expert/physician capacity and utilisation reports"]},{"title":"HR and Performance","price":24000,"currency":"TRY","duration_days":30,"revisions":2,"features":["Staff and HR tracking","Monthly targets and performance","Management dashboard and reports"]}],"html":"Occupational health and safety providers run statutory compliance software to report to the authority — but that software does not run the business. Who visited which client, which visit was missed, whether an expert''s capacity is full, how much will be invoiced this month, who has not paid: all of that usually stays in Excel.\\n\\nThe OHS Provider Management System closes exactly that layer: client records, visit calendars with missed-visit alerts, automatic revenue calculation from per-capita pricing, expert and physician capacity, task tracking, archive and document checklists, health report tracking, roles and permissions. Existing Excel and registry data is migrated; nothing is re-entered. Your data stays yours and can be exported at any time. There is no per-user pricing.","llms_summary":"GZL Teknoloji builds management systems for occupational health and safety (OHS) service providers: client and contract management, site visit tracking, automatic revenue calculation, expert capacity, health reports, archive and collections. It complements, rather than replaces, statutory compliance software.","tags":["OHS","Occupational Health and Safety","Vertical Software","Business Management"]}', 'OHS provider management system screen', 'OHS Provider Management System | GZL Teknoloji', 'Manage clients, site visits, expert capacity, revenue and collections of your OHS company from a single panel.', 'OHS software, occupational health and safety software, site visit tracking, vertical SaaS'),
('10000003-0000-4000-8000-020000000001', '10000000-0000-4000-8000-020000000001', 'de', 'betriebsfuehrungssystem-arbeitsschutzdienste', 'Betriebsführungssystem für Arbeitsschutzdienste', 'Verwalten Sie Kunden, Arbeitsschutzbesuche, Fachkraft-Kapazität, Monatsumsatz und Forderungen Ihres Arbeitsschutzdienstes in einem einzigen Panel. Compliance-Software meldet an die Behörde; sie führt nicht Ihren Betrieb.', '{"source":"vertical_product","segment":"Arbeitsschutz","packages":[{"title":"Operativer Kern","price":60000,"currency":"TRY","duration_days":30,"revisions":2,"features":["Kunden- und Vertragsverwaltung","Besuchsverfolgung mit Warnung bei fehlenden Besuchen","Aufgabenverwaltung","Archiv und Dokumenten-Checkliste","Gesundheitsberichte","Rollen und Berechtigungen","Datenübernahme aus Excel"]},{"title":"Kaufmännische Verwaltung","price":36000,"currency":"TRY","duration_days":30,"revisions":2,"features":["Automatische Umsatzberechnung","Angebotsprozesse","Forderungs- und Zahlungsverfolgung","Kapazitäts- und Auslastungsberichte"]},{"title":"Personal und Leistung","price":24000,"currency":"TRY","duration_days":30,"revisions":2,"features":["Personalverwaltung","Monatsziele und Leistung","Management-Dashboard und Berichte"]}],"html":"Arbeitsschutzdienste nutzen gesetzlich vorgeschriebene Compliance-Software für Meldungen an die Behörde — diese führt jedoch nicht den Betrieb. Wer hat welchen Kunden besucht, welcher Besuch fehlt, ist die Kapazität der Fachkraft ausgelastet, wie viel wird diesen Monat abgerechnet, wer hat nicht bezahlt: all das bleibt meist in Excel.\\n\\nDas Betriebsführungssystem schließt genau diese Ebene: Kundenakten, Besuchskalender mit Fehlwarnungen, automatische Umsatzberechnung, Kapazität von Fachkräften und Ärzten, Aufgabenverfolgung, Archiv und Checklisten, Gesundheitsberichte, Rollen und Berechtigungen. Vorhandene Daten werden importiert. Ihre Daten gehören Ihnen und sind jederzeit exportierbar. Keine Abrechnung pro Benutzer.","llms_summary":"GZL Teknoloji entwickelt Betriebsführungssysteme für Arbeitsschutzdienste: Kunden- und Vertragsverwaltung, Besuchsverfolgung, automatische Umsatzberechnung, Kapazitätssteuerung, Gesundheitsberichte, Archiv und Forderungsverfolgung. Ergänzt die gesetzliche Compliance-Software, ersetzt sie nicht.","tags":["Arbeitsschutz","Arbeitssicherheit","Branchensoftware","Betriebsführung"]}', 'Betriebsführungssystem für Arbeitsschutzdienste', 'Betriebsführungssystem für Arbeitsschutzdienste | GZL Teknoloji', 'Verwalten Sie Kunden, Besuche, Kapazität, Umsatz und Forderungen Ihres Arbeitsschutzdienstes in einem Panel.', 'Arbeitsschutz Software, Branchensoftware, Besuchsplanung, Betriebsführung')
ON DUPLICATE KEY UPDATE
  `slug` = VALUES(`slug`),
  `name` = VALUES(`name`),
  `summary` = VALUES(`summary`),
  `content` = VALUES(`content`),
  `image_alt` = VALUES(`image_alt`),
  `meta_title` = VALUES(`meta_title`),
  `meta_description` = VALUES(`meta_description`),
  `meta_keywords` = VALUES(`meta_keywords`),
  `updated_at` = CURRENT_TIMESTAMP(3);

