INSERT INTO `faqs_i18n` (`id`, `faq_id`, `locale`, `question`, `answer`, `slug`) VALUES
('50000001-0000-4000-8000-020000000001', '50000000-0000-4000-8000-020000000001', 'tr', 'OSGB işletme yönetim sistemi İBYS yazılımının yerine mi geçiyor?', 'Hayır. İBYS, İSG profesyonellerinin Bakanlığa veri göndermesi için kullanılan yasal uyum yazılımıdır ve kullanılmaya devam edilir. OSGB İşletme Yönetim Sistemi, İBYS''nin kapsamadığı işletme yönetimi katmanını kapatır: firma takibi, ziyaret planlama, otomatik ciro hesabı, tahsilat ve uzman kapasitesi. İkisi birlikte çalışır.', 'osgb-isletme-yonetim-sistemi-ibys-yerine-mi-geciyor'),
('50000002-0000-4000-8000-020000000001', '50000000-0000-4000-8000-020000000001', 'en', 'Does the OHS management system replace statutory compliance software?', 'No. Compliance software is used to report to the authority and remains in place. Our system covers the business-management layer it does not address: client tracking, visit planning, automatic revenue calculation, collections and expert capacity. The two work side by side.', 'does-ohs-system-replace-compliance-software'),
('50000003-0000-4000-8000-020000000001', '50000000-0000-4000-8000-020000000001', 'de', 'Ersetzt das System die gesetzliche Compliance-Software?', 'Nein. Die Compliance-Software bleibt für Meldungen an die Behörde in Betrieb. Unser System deckt die Betriebsführungsebene ab: Kundenverfolgung, Besuchsplanung, automatische Umsatzberechnung, Forderungen und Kapazitätssteuerung.', 'ersetzt-das-system-die-compliance-software'),
('50000001-0000-4000-8000-020000000002', '50000000-0000-4000-8000-020000000002', 'tr', 'Mevcut Excel ve İSG-KATİP verilerim aktarılıyor mu?', 'Evet. Kurulumun ilk adımı mevcut verinizin aktarılmasıdır. Firmalar, personel, atamalar, aylık ziyaret kayıtları ve fiyat bilgileri sisteme taşınır; hiçbir veri sıfırdan girilmez. Verileriniz size aittir ve dilediğiniz zaman dışa aktarabilirsiniz.', 'mevcut-excel-ve-isg-katip-verilerim-aktariliyor-mu'),
('50000002-0000-4000-8000-020000000002', '50000000-0000-4000-8000-020000000002', 'en', 'Is my existing Excel and registry data migrated?', 'Yes. The first step of onboarding is migrating your existing data: clients, staff, assignments, monthly visit records and pricing. Nothing is re-entered from scratch, and your data remains yours and exportable at any time.', 'is-my-existing-data-migrated'),
('50000003-0000-4000-8000-020000000002', '50000000-0000-4000-8000-020000000002', 'de', 'Werden meine vorhandenen Excel-Daten übernommen?', 'Ja. Der erste Schritt ist die Übernahme Ihrer vorhandenen Daten: Kunden, Personal, Einsätze, monatliche Besuchsdaten und Preise. Nichts wird neu eingegeben; Ihre Daten gehören Ihnen und sind jederzeit exportierbar.', 'werden-meine-excel-daten-uebernommen'),
('50000001-0000-4000-8000-020000000003', '50000000-0000-4000-8000-020000000003', 'tr', 'Fiyatlandırma kullanıcı başına mı?', 'Hayır. Uzman, hekim ve ofis personelinizin tamamını sisteme ekleyebilirsiniz; kullanıcı başına ücret alınmaz. Fiyat, OSGB''nizin ölçeğine (hizmet verilen firma ve çalışan sayısı) göre belirlenir ve modüler olarak genişletilebilir.', 'fiyatlandirma-kullanici-basina-mi'),
('50000002-0000-4000-8000-020000000003', '50000000-0000-4000-8000-020000000003', 'en', 'Is pricing per user?', 'No. You can add all of your experts, physicians and office staff at no per-user cost. Pricing is based on the scale of your organisation and can be extended module by module.', 'is-pricing-per-user'),
('50000003-0000-4000-8000-020000000003', '50000000-0000-4000-8000-020000000003', 'de', 'Wird pro Benutzer abgerechnet?', 'Nein. Sie können Ihr gesamtes Team ohne Zusatzkosten anlegen. Der Preis richtet sich nach der Größe Ihrer Organisation und lässt sich modular erweitern.', 'wird-pro-benutzer-abgerechnet')
ON DUPLICATE KEY UPDATE
  `question` = VALUES(`question`),
  `answer` = VALUES(`answer`),
  `slug` = VALUES(`slug`),
  `updated_at` = CURRENT_TIMESTAMP(3);
